// Simply 5 Cookbook (WW) - Breakfast ("Rise and shine"). Recipes only, no photos.
// Amounts marked (check) were blurry in the photo and still need confirming.
(function(){
const C = "";
const R = [
{ slug:"gruyere-asparagus-frittata", section:"found", title:"Gruyère and Asparagus Frittata", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","oven","vegetarian"], serves:"4", credit:C,
  summary:"Quick skillet frittata with asparagus, shallot, and nutty Gruyère, finished under the broiler.",
  ingredients:[{items:[
    "2 tsp olive oil","10 asparagus spears, trimmed and cut into 1-inch pieces","1 large shallot, minced",
    "5 large eggs","1 tbsp water","½ tsp salt","¼ tsp black pepper",
    "¼ cup shredded Gruyère or Swiss cheese"]}],
  steps:[
    "Preheat the broiler.",
    "Heat the oil in a 10-inch ovenproof skillet over medium-high heat. Cook the asparagus and shallot, stirring often, until softened, about 4 minutes.",
    "Beat the eggs, water, salt, and pepper in a medium bowl, then stir in the Gruyère. Pour over the asparagus and stir gently to combine. Reduce heat to medium and cook, covered, until the eggs are set in the center, about 5 minutes.",
    "Broil 5 inches from the heat until lightly browned, about 1 minute. Let stand about 2 minutes, then cut into wedges."],
  notes:[] },
{ slug:"overstuffed-western-omelette", section:"found", title:"Overstuffed Western Omelette", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","ham","skillet"], serves:"2", credit:C,
  summary:"Diner-style western omelette: the peppers, scallions, and ham cook first, then the eggs are poured over and folded.",
  ingredients:[{items:[
    "2 tsp canola oil","½ cup diced red bell pepper","½ cup diced green bell pepper","2 scallions, thinly sliced",
    "¼ pound low-sodium ham, diced","¼ tsp salt","⅛ tsp black pepper","4 large eggs, lightly beaten"]}],
  steps:[
    "Heat the oil in a medium nonstick skillet over medium heat. Add the bell peppers, scallions, ham, salt, and pepper and cook, stirring, until the vegetables soften, about 5 minutes.",
    "Pour the eggs over the vegetable mixture and cook until almost set, about 2 minutes, gently lifting the edge of the eggs with a silicone spatula so the uncooked egg runs underneath. Fold the omelette in half and cook until set, about 1 minute longer. Cut in half and serve one portion per plate."],
  notes:["**Heartier:** add ½ cup packaged diced cooked potatoes (refrigerated produce section) to the skillet with the peppers in step 1."] },
{ slug:"broccoli-egg-strudel", section:"found", title:"Broccoli-Egg Strudel", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","phyllo","vegetarian","brunch"], serves:"6", credit:C,
  summary:"Scrambled broccoli and Jarlsberg rolled in crisp layered phyllo and baked.",
  ingredients:[{items:[
    "2 cups small broccoli florets","10 sheets phyllo dough (9 x 14-inch), thawed if frozen","4 large eggs",
    "½ tsp salt","¼ tsp black pepper","2 tsp olive oil","½ cup shredded reduced-fat Jarlsberg cheese",
    "Nonstick spray"]}],
  steps:[
    "Preheat the oven to 375°F. Spray a rimmed baking sheet with nonstick spray.",
    "Bring a medium saucepan of water to a boil. Add the broccoli and cook until crisp-tender, about 3 minutes. Drain and pat dry with paper towels.",
    "Lay 1 phyllo sheet on a work surface with a long side facing you. Keep the rest covered with a damp kitchen towel and plastic wrap so it doesn't dry out. Lightly spray the sheet, then layer 9 more sheets on top, spraying each one. Cover with plastic wrap.",
    "Beat the eggs, salt, and pepper in a medium bowl. Stir in the broccoli.",
    "Heat the oil in a medium nonstick skillet over medium heat. Add the egg mixture and cook, stirring with a silicone spatula, just until set, about 2 minutes. Spoon over the phyllo, leaving a 2-inch border. Sprinkle with the Jarlsberg.",
    "Fold the short sides of the phyllo over the filling, then gently roll up jelly-roll style. Place seam-side down on the baking sheet. Lightly spray, and cut four 1-inch slits in the top to let steam out.",
    "Bake until golden and the filling is hot, about 20 minutes. Cool on a wire rack 15 minutes, then cut into 6 slices."],
  notes:[] },
{ slug:"zucchini-goat-cheese-omelette", section:"found", title:"Zucchini and Goat Cheese Omelette", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","vegetarian","skillet"], serves:"1", credit:C,
  summary:"Single-serve omelette filled with sautéed zucchini, goat cheese, and basil.",
  ingredients:[{items:[
    "2 tsp olive oil, divided","1 small zucchini, cut into matchstick strips","2 large egg whites","1 large egg",
    "¼ tsp salt","⅛ tsp black pepper","2 tbsp crumbled soft goat cheese","4 fresh basil leaves, thinly sliced"]}],
  steps:[
    "Heat 1 tsp oil in a small nonstick skillet over medium heat. Cook the zucchini, stirring, until crisp-tender, about 2 minutes. Move to a small bowl and set aside.",
    "Whisk the egg whites, egg, salt, and pepper in a small bowl.",
    "Heat the remaining 1 tsp oil in the same skillet (no need to wash it) over medium heat. Pour in the eggs and tilt the pan so they cover the bottom. Cook without stirring until the bottom is set and the top is almost set, about 2 minutes.",
    "Spoon the zucchini onto one half of the eggs and sprinkle with the goat cheese and basil. Fold the other half over to enclose and cook until set, about 1 minute longer."],
  notes:[] },
{ slug:"baked-eggs-tomatoes-florentine", section:"found", title:"Baked Eggs in Tomatoes Florentine", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","oven","vegetarian","brunch"], serves:"4", credit:C,
  summary:"Hollowed tomatoes stuffed with Parmesan spinach, each with an egg baked inside.",
  ingredients:[{items:[
    "4 ripe tomatoes (½ pound each)","½ tsp table salt, divided","2 tbsp grated Parmesan cheese",
    "1 tbsp Italian-seasoned dried bread crumbs","2 tsp olive oil","1 (5-ounce) container baby spinach",
    "¼ tsp black pepper, plus more for serving","4 large eggs","Large pinch coarse sea salt, such as Maldon"]}],
  steps:[
    "Preheat the oven to 400°F. Line a medium baking sheet with parchment paper.",
    "Cut a ½-inch slice off the top of each tomato and discard. With a grapefruit knife or small serrated knife, cut around the inside and remove the fleshy center. Scoop out the juicy pulp and seeds with a spoon and press through a small sieve set over a cup. Measure out ¼ cup tomato water and save it; discard the rest. Sprinkle the tomato shells with ¼ tsp of the table salt.",
    "Mix the Parmesan and bread crumbs in a cup.",
    "Heat the oil in a large skillet over medium heat. Add the spinach, the remaining ¼ tsp table salt, ¼ tsp pepper, and the reserved tomato water. Cook, stirring, until the spinach is wilted and the liquid has evaporated, about 3 minutes. Stir in the Parmesan-crumb mixture.",
    "Place the tomatoes on the baking sheet and bake 6 minutes. Spoon the spinach into the tomatoes, dividing evenly and using the back of the spoon to line the shells and leave the centers empty. Crack 1 egg into a cup and slip it into a tomato. Repeat.",
    "Cover the tomatoes with a sheet of nonstick foil and bake 10 minutes. Uncover and bake until the tomatoes are tender, whites are set, and yolks are slightly runny, about 10 minutes more. Sprinkle each egg with pepper and coarse salt."],
  notes:["A grapefruit knife (angled tip, serrated on both sides) is the easiest way to hollow out a tomato."] },
{ slug:"greek-style-breakfast-pitas", section:"found", title:"Greek-style Breakfast Pitas", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","quick","vegetarian"], serves:"2", credit:C,
  summary:"Soft scrambled eggs with feta, spinach, and tomatoes tucked into toasted whole wheat pita.",
  ingredients:[{items:[
    "3 large eggs","¼ cup crumbled reduced-fat feta cheese","¼ tsp black pepper","⅛ tsp salt",
    "1 cup tightly packed baby spinach","½ cup grape or cherry tomatoes, halved",
    "1 large whole wheat pita bread, halved and toasted","Nonstick spray"]}],
  steps:[
    "Beat the eggs in a small bowl. Stir in the feta, pepper, and salt.",
    "Spray a medium heavy skillet with nonstick spray and set over medium-high heat. Add the spinach and cook, stirring occasionally, until wilted, about 2 minutes.",
    "Reduce heat to medium. Add the egg mixture and tomatoes and cook, stirring frequently, until the eggs are just set, about 1½ minutes. Spoon evenly into the pita halves."],
  notes:["Optional: add ¼ tsp dried Greek seasoning and 2–3 tsp chopped fresh oregano."] },
{ slug:"bacon-cheddar-coddled-eggs", section:"found", title:"Bacon and Cheddar–Coddled Eggs", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","oven","bacon"], serves:"4", credit:C,
  summary:"Eggs baked in individual cups with spinach, bacon, and Cheddar. Good with toast fingers for dunking.",
  ingredients:[{items:[
    "½ cup thawed frozen chopped spinach, squeezed dry","4 large eggs","¼ tsp black pepper","⅛ tsp salt",
    "4 slices packaged fully cooked bacon, broken into pieces or chopped",
    "¼ cup shredded reduced-fat Cheddar or Swiss cheese","Nonstick spray"]}],
  steps:[
    "Preheat the oven to 350°F. Spray 4 (8-ounce) custard cups or ramekins with nonstick spray and place on a small rimmed baking sheet.",
    "Divide the spinach among the cups. Beat the eggs, pepper, and salt in a medium bowl and pour evenly into the cups. Top with the bacon and sprinkle each with 1 tbsp Cheddar. Bake until the eggs are just set, about 20 minutes."],
  notes:[] },
{ slug:"skinny-breakfast-sausages-eggs", section:"found", title:"Skinny Breakfast Sausages and Eggs", subtitle:"",
  category:"Breakfast & Brunch", tags:["eggs","sausage","skillet"], serves:"4", credit:C,
  summary:"Homemade turkey breakfast sausage patties with sage and thyme, served with eggs any style.",
  ingredients:[{items:[
    "½ pound ground turkey (7% fat or less)","2–3 tsp finely chopped fresh sage, or 1 tsp dried",
    "1 tsp finely chopped fresh thyme","¼ tsp salt, or to taste","¼ tsp black pepper",
    "4 large eggs, poached, scrambled, or fried","Nonstick spray"]}],
  steps:[
    "Combine the turkey, sage, thyme, salt, and pepper in a large bowl. Gently mix with a fork until evenly blended but not overmixed.",
    "Put a sheet of parchment or nonstick foil on the counter. Divide the turkey mixture into 8 equal portions (about 2 tbsp each). With damp hands, shape into 2½-inch patties. Don't worry if the edges are craggy or cracked.",
    "Spray a large nonstick skillet generously and set over medium heat. Cook the patties until lightly browned and just cooked through, about 2 minutes per side. Serve with eggs."],
  notes:["Serving is 2 patties and 1 egg."] },
{ slug:"cheddar-grits-bacon-kale", section:"found", title:"Cheddar Grits with Bacon and Kale", subtitle:"",
  category:"Breakfast & Brunch", tags:["grits","bacon","cheese"], serves:"4", credit:C,
  summary:"Creamy quick grits topped with Cajun-spiced kale, Canadian bacon, and Cheddar.",
  ingredients:[{items:[
    "4 cups water","1 cup quick-cooking grits","3 cups lightly packed torn kale","2 tsp Cajun seasoning","¼ tsp salt",
    "4 (¾-ounce) slices Canadian bacon, diced","½ cup shredded reduced-fat Cheddar cheese","Olive oil nonstick spray"]}],
  steps:[
    "Bring the water to a boil in a medium saucepan. Slowly whisk in the grits so they don't clump. Reduce heat to medium-low and cook, stirring occasionally, until thickened, about 5 minutes. Remove from heat and cover to keep warm.",
    "Meanwhile, heat a large skillet over medium-high heat. Add the kale and spray with olive oil nonstick spray, tossing to coat. Cook, stirring often, until wilted and any liquid has evaporated, about 2 minutes. Stir in the Cajun seasoning and salt.",
    "Push the kale to one side. Add the Canadian bacon and cook, stirring once or twice, until heated through, about 1 minute.",
    "Spoon the grits into 4 bowls, top with the kale and bacon, and sprinkle each with 2 tbsp Cheddar."],
  notes:["Serves well with a citrus salad of grapefruit and orange segments, fresh mint, and pomegranate arils."] }
];

function mk(slug,title,page,category,tags,serves,summary,items,steps,notes){
  return {slug,section:"found",title,subtitle:"",category,tags,serves,credit:C,summary,ingredients:[{items}],steps,notes:notes||[]};
}
R.push(
mk("chilaquiles-bake","Chilaquiles Bake",16,"Breakfast & Brunch",["eggs","oven","Tex-Mex"],"4",
 "Eggs baked in custard cups with black beans, corn tortilla strips, pepper Jack, and salsa verde.",
 ["⅓ cup canned black beans, rinsed and drained","1 (6-inch) corn tortilla, cut in half and then crosswise into thin strips","⅓ cup shredded reduced-fat pepper Jack cheese","6 large eggs","⅓ cup plus ¼ cup fat-free salsa verde","Nonstick spray"],
 ["Preheat the oven to 350°F. Spray 4 (6-ounce) custard cups or ramekins with nonstick spray.","Divide the beans, tortilla strips, and cheese evenly among the cups. Lightly beat the eggs in a medium bowl and stir in ⅓ cup of the salsa. Pour evenly into the cups and set them on a small rimmed baking sheet. Bake until the eggs are just set in the center, about 30 minutes. Serve with the remaining ¼ cup salsa."],
 ["**Optional:** top each with a 2-tablespoon dollop of light sour cream, chopped fresh cilantro, and thin jalapeño rings."]),
mk("maple-breakfast-pudding","Maple Breakfast Pudding",20,"Breakfast & Brunch",["rice","vegan","make-ahead"],"4",
 "Brown rice simmered in soy milk with raisins, maple syrup, and cinnamon, like a warm rice pudding.",
 ["2½ cups plain unsweetened soy milk","¾ cup long-grain brown rice","¼ cup raisins or dried cranberries","1 tbsp maple syrup","¾ tsp ground cinnamon","¼ tsp salt"],
 ["Bring the soy milk to a boil in a medium saucepan over medium-high heat. Stir in the rice, raisins, maple syrup, cinnamon, and salt. Return to a boil, then reduce heat to low and cook, covered, until the rice is tender and the milk is almost absorbed, about 45 minutes.","Remove from the heat and let stand 10 minutes before serving."]),
mk("polenta-brown-sugar-ricotta","Polenta with Brown Sugar Ricotta",21,"Breakfast & Brunch",["polenta","quick","vegetarian"],"4",
 "Creamy instant polenta topped with a smooth brown sugar and vanilla ricotta.",
 ["1 cup low-fat (1%) milk","1 cup water","⅛ tsp salt","⅔ cup part-skim ricotta cheese","1 tbsp light brown sugar","½ tsp vanilla extract","½ cup instant polenta"],
 ["Combine the milk, water, and salt in a medium saucepan and bring to a boil over medium-high heat.","Meanwhile, process the ricotta, brown sugar, and vanilla in a food processor until smooth. Set aside.","Slowly add the polenta to the milk mixture in a thin, steady stream, whisking constantly. Cook, stirring constantly, until thickened and creamy, 3–5 minutes. Divide among 4 bowls and top with the ricotta mixture."],
 ["Sprinkle with finely grated lemon or orange zest or ground cinnamon."]),
mk("red-white-blue-parfaits","Red, White, and Blue Parfaits",23,"Breakfast & Brunch",["yogurt","make-ahead","no-cook"],"4",
 "Chia yogurt layered with mixed berries and granola in jars. Make the yogurt the night before.",
 ["2 cups plain low-fat yogurt","2 tbsp chia seeds","½ tsp grated lemon zest","2 cups mixed berries (raspberries, blueberries, and sliced strawberries)","½ cup low-fat granola"],
 ["Combine the yogurt, chia seeds, and lemon zest in a medium bowl. Cover and refrigerate until the chia seeds soften, at least 4 hours or overnight.","Spoon ½ cup of the yogurt mixture into each of 4 mason jars or glasses. Top each with ½ cup berries and 2 tablespoons granola."]),
mk("gin-basil-smash","Gin-Basil Smash",27,"Drinks",["cocktail","gin","party"],"6",
 "Gin, lemon juice, and muddled basil shaken with agave.",
 ["⅓ cup lightly packed Thai, lemon, or regular basil leaves, plus leaves for garnish","1 cup gin","½ cup lemon juice","3–4 tbsp light agave nectar","1 cup ice cubes, plus more for serving"],
 ["Put the basil in a cocktail shaker and gently muddle with a muddler or wooden spoon, just until the basil smells fragrant.","Add the remaining ingredients, cover, and shake hard until the outside of the shaker feels icy.","Strain into 4 ice-filled small wineglasses and garnish with basil leaves."],
 ["Top each with seltzer for a spritzer."]),
mk("watermelon-mojitos","Watermelon Mojitos",28,"Drinks",["cocktail","vodka","party","summer"],"6",
 "Pitcher mojitos made with fresh watermelon juice and vodka.",
 ["⅓ cup lightly packed fresh mint leaves","6 cups tightly packed 1½-inch watermelon chunks","1 cup vodka","¼ cup lime juice","1 tbsp light agave nectar, or to taste","Ice cubes","Watermelon spears, thinly sliced lime, and/or fresh mint sprigs, for garnish"],
 ["Put the mint in a pitcher and gently muddle.","Blend the watermelon on low speed until smooth. Pour through a fine-mesh sieve set over a medium bowl, pressing hard on the solids; discard the solids. Skim the foam off the juice and discard.","Add the watermelon juice to the pitcher and stir in the vodka, lime juice, and agave. Pour into 6 ice-filled glasses and garnish."]),
mk("mango-coconut-agua-fresca","Mango-Coconut Agua Fresca",29,"Drinks",["non-alcoholic","summer","blender"],"8",
 "Blended mango and coconut water, thinned with ice water and finished with lime.",
 ["4 cups pure coconut water, preferably with pulp","2 ripe mangoes, peeled, pitted, and cubed (about 3 cups)","3–4 tbsp lime juice","Ice-cold water","Ice cubes","Lime wedges"],
 ["Blend the coconut water and mango until smooth. Stir in the lime juice and add enough ice-cold water to make 8 cups.","Pour into 8 ice-filled glasses and garnish with lime wedges."]),
mk("coconut-cucumber-splash","Coconut-Cucumber Splash",31,"Drinks",["non-alcoholic","make-ahead","summer"],"4",
 "Chilled coconut water with cucumber, lime, agave, and ginger.",
 ["1 (33½-ounce) carton coconut water, chilled","1 mini cucumber, thinly sliced on the diagonal","Juice of 1 lime","1 tbsp light agave nectar","1 tbsp grated peeled fresh ginger or refrigerated ginger paste","Ice cubes"],
 ["Pour the coconut water into a large pitcher. Add the cucumber, lime juice, agave, and ginger and stir until well mixed.","Refrigerate at least 2 hours or up to 1 day. Pour into 4 ice-filled glasses."],
 ["Mint sprigs make a nice garnish."]),
mk("mustardy-deviled-eggs","Mustardy Deviled Eggs",33,"Appetizers & Dips",["eggs","party","make-ahead"],"6",
 "Deviled eggs with Dijon, a touch of white vinegar, and a little hot sauce.",
 ["6 large eggs","3 tbsp reduced-fat mayonnaise","1½ tsp Dijon mustard","1 tsp white vinegar","¼ tsp hot pepper sauce","¼ tsp black pepper, plus more for sprinkling","⅛ tsp salt"],
 ["Put the eggs in a medium saucepan with enough cold water to cover by at least 1 inch and bring to a boil. Immediately remove from the heat, cover, and let stand 12 minutes. Pour off the water and rinse the eggs under cold running water to cool slightly.","Peel the eggs and cut lengthwise in half. Move the yolks to a small bowl and mash with a fork until smooth. Add the remaining ingredients and stir until well combined.","Spoon the yolk mixture into a small plastic bag and snip off a corner, or use a pastry bag with a star tip. Pipe evenly into the whites. Arrange on a platter and sprinkle with pepper."],
 ["Serve right away, or cover loosely and refrigerate up to 4 hours; let stand 15 minutes at room temperature before serving."]),
mk("provencal-tomato-tart","Provençal Tomato Tart",38,"Appetizers & Dips",["tomato","phyllo","vegetarian","party"],"12",
 "Crisp phyllo shell with overlapping tomato slices, Kalamata olives, thin onion, and Parmesan.",
 ["5 large red or yellow plum tomatoes, or a combination, cut into ¼-inch slices","1 onion, very thinly sliced","16 pitted Kalamata olives, quartered","½ tsp salt","¼ tsp black pepper","8 (12 x 17-inch) sheets phyllo dough, thawed if frozen","½ cup grated Parmesan cheese","Olive oil nonstick spray"],
 ["Set an oven rack in the lower third and preheat the oven to 425°F.","Place the tomato slices between double layers of paper towels and pat dry. Let stand 10 minutes.","Toss the onion, olives, salt, and pepper in a small bowl.","Lay 1 phyllo sheet on a large baking sheet and lightly spray with olive oil nonstick spray. (Keep the remaining phyllo covered with a damp kitchen towel and plastic wrap.) Repeat with the remaining 7 sheets, spraying each. Roll the edges in to form a rim.","Arrange the tomato slices on the phyllo in a single overlapping layer. Top with the onion mixture and lightly spray. Bake until the bottom and edges are golden and the onion is softened, 25–35 minutes. Sprinkle with Parmesan and cut into 12 pieces. Serve hot, warm, or at room temperature."]),
mk("reuben-style-quesadillas","Reuben-Style Quesadillas",41,"Appetizers & Dips",["turkey","quick","skillet"],"8",
 "Turkey, coleslaw, Swiss, and Thousand Island in whole wheat tortillas, browned in a skillet.",
 ["½ cup Thousand Island dressing","4 (7-inch) reduced-fat whole wheat tortillas","1 (¼-pound) piece skinless roasted turkey, shredded","1 cup tightly packed coleslaw mix","½ cup shredded reduced-fat Swiss cheese","Nonstick spray"],
 ["Spread 1 tbsp of dressing on one half of each tortilla. Layer one-fourth of the turkey, coleslaw, and Swiss over the dressing. Fold the unfilled half over the filling, pressing down gently. Spray the tops with nonstick spray.","Place 2 quesadillas, sprayed side down, in a large skillet over medium-high heat. Cook until crisp and browned in spots, about 3 minutes. Spray the tops, turn over, and cook until browned in spots and the cheese is melted, about 2 minutes longer.","Move to a cutting board and cover to keep warm. Repeat with the remaining 2. Cut each in half and serve with the remaining ¼ cup dressing."],
 ["For a more traditional Reuben, spread a thin layer of well-drained sauerkraut over the slaw."]),
mk("parmesan-pepper-green-bean-fries","Parmesan-Pepper Green Bean \"Fries\"",43,"Appetizers & Dips",["vegetable","oven","snack"],"6",
 "Green beans dipped in egg white, coated in Parmesan and black pepper, and baked until crisp.",
 ["2 large egg whites, at room temperature","2 tbsp water","1 cup grated Parmesan cheese","1 tsp black pepper","¾ pound green beans, trimmed"],
 ["Preheat the oven to 425°F. Line a large rimmed baking sheet with a silicone baking mat or parchment paper.","Whisk the egg whites and water in a shallow bowl until foamy. In another shallow bowl, mix the Parmesan and pepper.","Dip the green beans one at a time into the egg white, letting the excess drip off. Coat with the Parmesan and arrange on the baking sheet about 1 inch apart.","Bake until the Parmesan is melted and lightly browned, about 8 minutes. Transfer the beans with the sheet to a wire rack and let cool slightly before serving."]),
mk("silky-chickpea-soup-cumin","Silky Chickpea Soup with Cumin",50,"Soups & Stews",["soup","vegan","gluten-free"],"6",
 "Chickpea flour whisked into garlicky cumin broth, finished with lemon and olive oil.",
 ["1 tbsp cumin seeds","5½ cups water","2 large garlic cloves, minced","1¼ tsp salt","1 cup chickpea flour","2 tbsp lemon juice, plus 6 very thin lemon wedges","1 tbsp fruity extra-virgin olive oil"],
 ["Toast the cumin seeds in a medium saucepan over medium heat, shaking the pan occasionally, until slightly darker and fragrant, about 2 minutes. Move ½ tsp of the toasted seeds to a cup and save.","Add 4½ cups of the water, the garlic, and salt to the same pan and bring to a boil. Reduce the heat and simmer until the flavors blend, about 5 minutes.","Meanwhile, whisk the chickpea flour and the remaining 1 cup water in a medium bowl or glass measure until smooth, then gradually whisk into the garlic water. Cook, whisking occasionally, until thickened, about 3 minutes.","Remove from the heat and stir in the lemon juice. Ladle into 6 bowls and sprinkle with the reserved cumin seeds. Drizzle each with ½ tsp oil and top with a lemon slice."],
 ["Chickpea (garbanzo) flour is usually in the baking aisle (Bob's Red Mill) or specialty stores."]),
mk("fresh-corn-basil-soup","Fresh Corn-Basil Soup",52,"Soups & Stews",["soup","vegetarian","summer"],"6",
 "Fresh corn simmered in vegetable broth, partly blended, and topped with sliced basil.",
 ["1 tbsp canola oil","1 onion, chopped","3 large garlic cloves, minced","3 cups corn kernels (about 6 ears)","1 (32-ounce) carton vegetable broth","½ tsp salt","¼ tsp black pepper","Thinly sliced fresh basil leaves"],
 ["Heat the oil in a large pot or Dutch oven over medium heat. Cook the onion, stirring, until softened, about 5 minutes. Add the garlic and cook until fragrant, about 30 seconds. Add the corn and cook, stirring, until tender, about 5 minutes. Stir in the broth, salt, and pepper and bring to a boil. Reduce the heat and simmer 10 minutes. Remove from the heat and let cool 10 minutes.","Blend 3 cups of the soup until smooth. Return to the pot and cook over low heat until heated through, about 2 minutes. Ladle into 6 bowls and sprinkle with basil."]),
mk("north-african-red-lentil-soup","North African Red Lentil Soup",54,"Soups & Stews",["soup","lentils","quick"],"4",
 "Red lentils, garlicky diced tomatoes, and cumin, finished with cilantro and a spoonful of yogurt.",
 ["3 cups water","1 (14½-ounce) can diced tomatoes with garlic and onions","1 cup dried red lentils, picked over and rinsed","1 tsp ground cumin","¾ tsp salt","¼ tsp black pepper","⅓ cup chopped fresh cilantro","½ cup plain low-fat yogurt"],
 ["Combine the water, tomatoes, lentils, cumin, salt, and pepper in a medium saucepan and bring to a boil. Reduce the heat and simmer, covered, stirring occasionally, until the lentils are tender, about 30 minutes.","Remove from the heat and stir in the cilantro. Ladle into 4 bowls and top each with a 2-tablespoon dollop of yogurt."],
 ["If reheating, thin the soup with water as needed."]),
mk("soba-noodle-mushroom-soup","Soba Noodle–Mushroom Soup",57,"Soups & Stews",["soup","noodles","quick"],"6",
 "Chicken broth with white miso, shiitake mushrooms, soba noodles, and spinach.",
 ["3 ounces soba (100% buckwheat) noodles","6 cups chicken broth","1 tbsp white miso","¼ pound shiitake mushrooms, stems removed and caps sliced","4 cups lightly packed baby spinach"],
 ["Cook the noodles according to the package directions. Drain in a colander and rinse under cool running water; drain again.","Meanwhile, whisk the broth and miso in a large saucepan. Add the mushrooms and bring to a boil. Reduce the heat and simmer until the mushrooms are tender, about 5 minutes. Stir in the noodles and spinach and cook until the noodles are heated through and the spinach has wilted, about 3 minutes longer."],
 ["For a heartier soup, add ¼ pound cooked small shrimp or picked-over lump crabmeat with the noodles in step 2. Top with chopped fresh chives."]),
mk("chickpea-broccoli-soup","Chickpea-Broccoli Soup",63,"Soups & Stews",["soup","quick","vegetarian"],"4",
 "Fast tomato broth with broccoli and chickpeas, topped with Parmesan.",
 ["2 tsp olive oil","1 large garlic clove, minced","2 cups water","1 cup canned crushed tomatoes","¼ tsp salt, or to taste","¼ tsp black pepper, or to taste","2 cups small broccoli florets","1 cup canned chickpeas, rinsed and drained","¼ cup grated Parmesan cheese"],
 ["Heat the oil in a medium saucepan over medium heat. Add the garlic and cook, stirring constantly, until fragrant, about 30 seconds.","Add the water, tomatoes, salt, and pepper and bring to a boil. Add the broccoli and chickpeas; reduce the heat and simmer, covered, stirring occasionally, until the broccoli is tender, about 5 minutes.","Ladle into 4 bowls and sprinkle with the Parmesan."],
 ["Variation: use cauliflower instead of broccoli and cannellini beans instead of chickpeas. For more flavor, cook 1 small chopped onion in the oil about 5 minutes before adding the garlic."]),
mk("fresh-salmon-ginger-burgers","Fresh Salmon-Ginger Burgers",82,"Fish & Seafood",["fish","salmon","skillet"],"4",
 "Chopped salmon patties with fresh ginger and horseradish, topped with horseradish mayo.",
 ["1 slice white or whole wheat sandwich bread","2 tbsp minced peeled fresh ginger","8 tsp prepared horseradish sauce, such as cranberry-horseradish","1 pound skinless salmon fillet, cut into 1-inch pieces","¼ tsp salt","¼ tsp black pepper","2 tsp canola oil","¼ cup reduced-fat mayonnaise"],
 ["Tear the bread into pieces and pulse in a food processor until coarse crumbs form. Move to a large bowl and add the ginger and 4 tsp of the horseradish sauce. Pulse the salmon in the food processor until coarsely chopped. Add to the crumb mixture with the salt and pepper.","Gently stir with a fork until combined but not overmixed. With damp hands, shape into 4 (4-inch) patties.","Heat the oil in a large nonstick skillet over medium heat until hot. Cook the patties until golden brown and just opaque in the center, about 3 minutes per side.","Stir the mayonnaise and remaining 4 tsp horseradish sauce together in a cup. Dollop onto the burgers."],
 ["For the most ginger flavor, shape the patties, put them on a wax paper–lined plate, cover, and refrigerate at least 2 hours or up to 6 hours before cooking.","Serve on whole wheat sandwich thins with lettuce, tomato, and red onion."]),
mk("miso-glazed-salmon","Miso-Glazed Salmon",84,"Fish & Seafood",["fish","salmon","oven"],"4",
 "Salmon marinated in white miso, soy, and honey, baked and served with steamed baby bok choy.",
 ["2 tbsp white miso","2 tbsp reduced-sodium soy sauce","1½ tsp honey","4 (5-ounce) salmon fillets with skin","4 baby bok choy, halved lengthwise"],
 ["Line a small rimmed baking sheet with nonstick foil.","Stir the miso, soy sauce, and honey together in a cup. Put the salmon on the baking sheet and spoon the miso mixture over it. Marinate in the refrigerator at least 15 minutes or up to 2 hours, turning once or twice.","Preheat the oven to 425°F.","Bake the salmon, skin side down, until just opaque in the center, about 15 minutes.","Meanwhile, put the bok choy in a steamer basket set in a large skillet over 1 inch of boiling water. Cover and steam until tender, about 6 minutes. To serve, slide a spatula under the salmon flesh to separate it from the skin. Serve with the bok choy."]),
mk("flounder-in-crazy-water","Flounder in Crazy Water",87,"Fish & Seafood",["fish","flounder","skillet"],"4",
 "Flounder poached in a garlic-parsley broth with cherry tomatoes (pesce all'acqua pazza).",
 ["12 large fresh flat-leaf parsley sprigs","2 cups water","4 garlic cloves, thinly sliced","4 tsp extra-virgin olive oil","¾ tsp salt","¾ tsp black pepper","1½ pounds mixed baby heirloom tomatoes (2 pints), halved or quartered if large","4 (5- to 6-ounce) flounder fillets"],
 ["Separate the leaves and stems of 8 parsley sprigs; coarsely chop the leaves and save the other 4 sprigs. Put the parsley stems in a large deep skillet with the water, garlic, oil, salt, and pepper and bring to a boil. Reduce the heat to medium-low and simmer, partially covered, until the broth is fragrant and the garlic is tender, about 15 minutes.","Remove and discard the stems. Add the tomatoes and chopped parsley and return to a boil. Reduce the heat and simmer, uncovered, until the tomatoes are slightly softened, about 4 minutes. Fold the ends of each flounder fillet under to form neat packages. Using a pancake spatula, place the fish in the skillet and cook, covered, until just opaque in the center, about 7 minutes.","Using 2 spatulas, carefully move the fillets to 4 large shallow bowls or deep plates. Spoon the tomato mixture over the fish and top with the reserved parsley sprigs."])
);

function mk2(slug,title,page,category,tags,serves,summary,items,steps,notes){
  const r=mk(slug,title,page||"",category,tags,serves,summary,items,steps,notes);
  if(!page) r.subtitle="";
  return r;
}
R.push(
mk2("seared-scallops-edamame-puree","Seared Scallops with Edamame Puree",89,"Fish & Seafood",["seafood","scallops","skillet"],"4",
 "Golden seared sea scallops over a smooth, lemony edamame puree.",
 ["1¾ cups frozen shelled edamame","¾ tsp salt, divided","1 cup water","⅓ cup fat-free half-and-half, warmed","½ tsp black pepper, divided","1 lemon, halved","16 large sea scallops (about 1½ pounds), patted dry","1½ tsp canola oil"],
 ["Bring a small saucepan of water to a boil over high heat. Add the edamame and ¼ tsp of the salt and cook until tender, about 10 minutes. With a slotted spoon, remove ¼ cup of the edamame and save.","Put the remaining 1½ cups edamame in a blender with the 1 cup water. Add the half-and-half, ¼ tsp salt, and ¼ tsp pepper and blend into a smooth, thick puree, adding a little more water if needed. Return to the saucepan and stir in the juice of 1 lemon half. Keep warm over very low heat.","Sprinkle the scallops with the remaining ¼ tsp salt. Heat the oil in a large heavy nonstick skillet over medium-high heat until very hot. Add 8 scallops and sear until deep golden brown and barely translucent in the center, about 2 minutes per side. Move to a plate and loosely cover with foil. Cook the remaining 8 scallops.","Spoon the puree onto 4 plates and top each with 4 scallops. Sprinkle with the saved edamame and the remaining ¼ tsp pepper. Cut the other lemon half into 4 wedges and serve alongside."],
 ["Dry (day-boat or diver) scallops have no additives; sea scallops are often sold wet."]),
mk2("green-sauce-marinated-shrimp","Green Sauce–Marinated Shrimp",91,"Fish & Seafood",["seafood","shrimp","grill"],"4",
 "Shrimp marinated in a parsley, basil, and garlic sauce, then cooked on a grill pan.",
 ["⅓ cup chopped fresh flat-leaf parsley","⅓ cup chopped fresh basil","2 garlic cloves, crushed through a press","4 tsp olive oil","¼ tsp salt","¼ tsp black pepper","1½ pounds large shrimp, peeled and deveined","Lemon wedges","Nonstick spray"],
 ["Combine the parsley, basil, garlic, oil, salt, and pepper in a large zip-close bag and add the shrimp. Squeeze out the air, seal, and turn to coat. Refrigerate, turning occasionally, at least 1 hour or up to 6 hours. Remove the shrimp from the marinade and discard the marinade.","Spray a heavy nonstick ridged grill pan with nonstick spray and set over medium-high heat. Cook the shrimp, in batches if needed, until just opaque in the center, about 2 minutes per side. Serve with lemon wedges."]),
mk2("pecan-crusted-buttermilk-chicken","Pecan-Crusted Buttermilk Chicken",92,"Chicken & Turkey",["chicken","pecan","skillet","oven"],"4",
 "Chicken soaked in buttermilk, coated with pecans and bread crumbs, seared, then finished in the oven.",
 ["4 (5-ounce) skinless boneless chicken breasts","¾ cup low-fat buttermilk","⅓ cup plain dried bread crumbs","¼ cup pecans, finely chopped","1 tsp Cajun seasoning","1 tbsp canola oil","Nonstick spray"],
 ["Combine the chicken and buttermilk in a medium bowl and turn to coat. Refrigerate 20 minutes.","Meanwhile, preheat the oven to 350°F.","Mix the bread crumbs, pecans, and Cajun seasoning on a sheet of wax paper. Remove one piece of chicken from the buttermilk, letting the excess drip off. Coat with the pecan mixture, gently pressing so it sticks. Put on a separate sheet of wax paper. Repeat with the rest. Lightly spray the chicken on both sides with nonstick spray. Discard any leftover buttermilk and pecan mixture.","Heat the oil in a large heavy nonstick ovenproof skillet over medium-high heat. Cook the chicken until golden, about 2½ minutes per side. Move the skillet to the oven and bake until the chicken is cooked through, about 10 minutes longer."],
 ["A well-seasoned cast-iron skillet gives the best results."]),
mk2("chicken-black-bean-sauce","Chicken with Black Bean Sauce",94,"Chicken & Turkey",["chicken","stir-fry","asparagus"],"4",
 "Quick wok stir-fry of chicken strips and asparagus in black bean sauce.",
 ["4 tsp Asian (dark) sesame oil, divided","1 pound skinless boneless chicken breasts, cut on the diagonal into strips","½ tsp salt","1 tbsp grated peeled fresh ginger","1 (1-pound) bunch asparagus, trimmed and cut into 2-inch lengths","3 tbsp water","¼ cup black bean sauce"],
 ["Heat a wok or large heavy deep nonstick skillet over medium-high heat until hot. Add 2 tsp of the oil and swirl to coat. Sprinkle the chicken with the salt, add it to the wok, and stir-fry until cooked through, about 3 minutes. Move to a plate.","Wipe out the wok. Heat the remaining 2 tsp oil. Add the ginger and stir-fry until fragrant, about 30 seconds. Add the asparagus and water and cook, covered, until crisp-tender, about 2 minutes.","Return the chicken to the wok with the black bean sauce. Stir-fry until the chicken is heated through, about 1 minute longer."],
 ["Preheat the wok well so the chicken starts to sear the moment it hits the pan."]),
mk2("spicy-blue-cheese-chicken-burgers","Spicy Blue Cheese–Chicken Burgers",null,"Chicken & Turkey",["chicken","burgers","grill"],"4",
 "Hot-sauce chicken patties with scallions, cooked on a grill pan and drizzled with blue cheese dressing.",
 ["1 pound ground skinless chicken breast","2 scallions, thinly sliced","3 tbsp plain dried bread crumbs","2 tbsp hot pepper sauce, such as Frank's","½ tsp salt","¼ cup reduced-fat blue cheese dressing","Nonstick spray"],
 ["Mix the chicken, scallions, bread crumbs, pepper sauce, and salt in a medium bowl until well combined but not overmixed. With damp hands, shape into 4 (4-inch) patties.","Spray a ridged grill pan with nonstick spray and set over medium heat. Spray the patties, put them in the pan, and cook until an instant-read thermometer in the side of a burger reads 165°F, about 5 minutes per side. Drizzle with the blue cheese dressing."]),
mk2("chicken-kebabs-pineapple","Chicken Kebabs with Pineapple",97,"Chicken & Turkey",["chicken","grill","skewers"],"4",
 "Lime, jalapeño, and garlic–marinated chicken grilled on skewers with fresh pineapple.",
 ["Grated zest and juice of 1 lime","1 tbsp olive oil","1 jalapeño pepper, seeded and minced","2 garlic cloves, minced","½ tsp salt","¼ tsp black pepper","1 pound skinless boneless chicken breasts, cut into 1½-inch chunks","1½ cups fresh pineapple chunks","Nonstick spray"],
 ["Combine the lime juice, oil, jalapeño, garlic, salt, and pepper in a large zip-close bag and add the chicken. Squeeze out the air, seal, and turn to coat. Refrigerate, turning occasionally, at least 20 minutes or up to overnight.","Spray the grill rack with nonstick spray. Preheat the grill to medium or prepare a medium fire. Soak 4 (8- to 10-inch) wooden skewers in water at least 20 minutes.","Remove the chicken from the marinade and discard the marinade. Thread the chicken and pineapple alternately onto the skewers. Spray with nonstick spray and put on the grill rack. Grill, turning occasionally, until the chicken is cooked through, about 7 minutes. Sprinkle with the lime zest."],
 ["Good with grilled bell peppers on the side."]),
mk2("turkey-fingers-peach-sauce","Turkey Fingers with Peach Sauce",98,"Chicken & Turkey",["turkey","oven","kid-friendly"],"4",
 "Baked turkey strips with a coconut and panko crust, served with a curried peach dipping sauce.",
 ["½ cup peach or apricot all-fruit spread, divided","1 tsp curry powder, divided","1 (1-pound) piece skinless boneless turkey breast","¾ tsp salt","¼ tsp black pepper","½ cup unsweetened flaked coconut, chopped","¼ cup whole wheat panko bread crumbs","Nonstick spray"],
 ["Preheat the oven to 425°F. Spray a rimmed baking sheet with nonstick spray.","For the sauce, stir ¼ cup of the fruit spread and ½ tsp of the curry powder together in a serving bowl. Set aside.","Cut the turkey into 16 strips. Stir the remaining ¼ cup fruit spread, remaining ½ tsp curry powder, the salt, and pepper together in a medium bowl. Add the turkey and toss to coat.","Mix the coconut and panko on a sheet of wax paper. Coat the turkey strips one at a time, lightly pressing so it sticks. Arrange in a single layer on the baking sheet and spray with nonstick spray. Bake until golden and cooked through, about 15 minutes. Serve with the sauce."],
 ["For an appetizer, thread each cooked finger onto a small decorative wooden skewer."]),
mk2("pan-glazed-turkey-tenderloin","Pan-Glazed Turkey Tenderloin",99,"Chicken & Turkey",["turkey","skillet"],"4",
 "Turkey tenderloin browned and simmered in an apricot-Dijon-thyme pan sauce.",
 ["⅓ cup chicken broth","¼ cup apricot or peach all-fruit spread","2 tbsp Dijon mustard","1½ tsp chopped fresh thyme, or ½ tsp dried","1 tbsp canola oil","1 (1-pound) piece skinless boneless turkey tenderloin","½ tsp salt","¼ tsp black pepper"],
 ["Stir the broth, fruit spread, mustard, and thyme together in a small bowl.","Heat the oil in a large skillet over medium-high heat. Sprinkle the turkey with the salt and pepper, add it to the skillet, and cook, turning occasionally, until browned, about 5 minutes. Add the apricot mixture and bring to a boil. Reduce the heat and simmer, covered, until an instant-read thermometer in the center of the turkey reads 165°F, about 12 minutes longer.","Move the turkey to a cutting board and let stand 5 minutes. Cut into 8 slices and serve with the pan sauce."],
 ["Serve with black beans topped with diced red bell pepper and chopped cilantro."]),
mk2("grilled-turkey-saltimbocca","Grilled Turkey Saltimbocca",101,"Chicken & Turkey",["turkey","grill","prosciutto"],"4",
 "Turkey cutlets rolled around goat cheese, asparagus, and sage, wrapped in prosciutto and grilled.",
 ["32 pencil (thin) asparagus spears (about ¾ pound), trimmed","4 (¼-pound) turkey breast cutlets","¼ tsp salt","¼ tsp black pepper","¼ cup soft goat cheese","12 fresh sage leaves","8 (½-ounce) slices prosciutto","Nonstick spray"],
 ["Spray the grill rack with nonstick spray. Preheat the grill to medium or prepare a medium fire. Soak 4 short wooden skewers in water at least 20 minutes.","Bring 1 inch of salted water to a boil in a large skillet. Add the asparagus and cook, covered, until crisp-tender and bright green, about 2 minutes. With tongs, move to a bowl of ice water and cool about 2 minutes. Drain on a double layer of paper towels and pat dry.","Put the turkey cutlets between two pieces of plastic wrap and lightly pound to ¼-inch thickness. Remove the top layer of wrap. Sprinkle the turkey with the salt and pepper. Spread 1 tbsp goat cheese on each cutlet. Lay 8 asparagus spears crosswise on each cutlet and roll up from the short side. Put 3 sage leaves on each roll and wrap in 2 slices of prosciutto. Secure each with a skewer and lightly spray.","Put the rolls on the grill rack and grill, covered, turning occasionally, until the turkey is cooked through, about 12 minutes. Remove the skewers before eating."]),
mk2("hearty-turkey-barley-stew","Hearty Turkey-Barley Stew",102,"Soups & Stews",["stew","turkey","barley"],"6",
 "Turkey tenderloin, leeks, and pearl barley simmered with porcini mushrooms and their soaking liquid.",
 ["1 ounce best-quality dried porcini mushrooms","1½ cups boiling water","1 tbsp olive oil","1 (1-pound) piece skinless boneless turkey tenderloin, cut into ½-inch pieces","3 leeks (white and pale green parts only), thinly sliced","1 (32-ounce) carton chicken broth","½ cup pearl barley, rinsed","¾ tsp salt","¼ tsp black pepper"],
 ["Combine the mushrooms and boiling water in a small bowl and soak until softened, about 10 minutes. Pour the mushrooms and liquid through a paper towel–lined sieve set over a small bowl. Save the liquid and coarsely chop the mushrooms.","Heat the oil in a large saucepan over medium-high heat. Add the turkey and cook, stirring, until golden brown, about 8 minutes. Add the leeks and cook, stirring, until softened, about 5 minutes. Add the broth, barley, mushrooms and liquid, salt, and pepper and bring to a boil. Reduce the heat and simmer, covered, until the barley is tender, about 30 minutes longer."],
 ["Toss in a small handful of chopped fresh parsley and a couple of shakes of Worcestershire sauce just before serving."]),
mk2("kielbasa-lentil-stew","Kielbasa and Lentil Stew",104,"Soups & Stews",["stew","lentils","sausage"],"4",
 "Turkey kielbasa, onion, tomatoes, and green lentils simmered in one pot.",
 ["1 tbsp olive oil, divided","¾ pound turkey kielbasa, cut into 1-inch chunks","1 onion, thinly sliced","1 (14½-ounce) can diced tomatoes with Italian herbs","1 cup water","1 (15-ounce) can green lentils, drained, or 1½ cups vacuum-packed cooked green or brown lentils","¼ tsp salt","⅛ tsp black pepper"],
 ["Heat 2 tsp of the oil in a Dutch oven over medium-high heat. Cook the kielbasa, stirring, until browned, about 5 minutes. Move to a plate with a slotted spoon.","Heat the remaining 1 tsp oil in the same pan. Cook the onion, stirring occasionally, until golden, about 8 minutes. Reduce the heat to medium and add the tomatoes. Pour the water into the empty tomato can, swirl, and add to the pan along with the lentils, salt, and pepper. Bring to a simmer and cook, covered, 10 minutes.","Stir in the kielbasa and simmer, uncovered, until heated through and the flavors blend, about 5 minutes."]),
mk2("grilled-swiss-chard-tomato-pizzas","Grilled Swiss Chard and Tomato Pizzas",null,"Sandwiches & Pizza",["pizza","grill","vegetarian"],"8",
 "Grilled pizza rounds topped with grilled chard, red onion, plum tomatoes, and mozzarella.",
 ["1 (¾-pound) bunch Swiss chard, tough stems removed and leaves cut into large pieces","1 red onion, cut into ¼-inch rounds","1 pound refrigerated pizza dough, at room temperature","4 large plum tomatoes, cut crosswise into ¼-inch slices","¼ tsp black pepper","1 cup shredded part-skim mozzarella cheese","Olive oil nonstick spray"],
 ["Spray the grill rack with nonstick spray. Preheat the grill to medium-high or prepare a medium-high fire.","Spray the chard and onion with olive oil nonstick spray and put on the grill rack. Grill, turning, until lightly browned and tender, about 3 minutes for the chard and 5 minutes for the onion. Move to a cutting board as they finish and coarsely chop. Keep the grill on.","Divide the dough into 4 equal pieces. On a lightly floured surface with a floured rolling pin, roll each piece into a thin round. Lightly spray the tops. Put the rounds sprayed side down on the grill rack and grill until golden brown on the bottom, about 2 minutes.","With tongs, move the crusts to a cutting board or baking peel and turn cooked side up. Spray the crusts and top evenly with the chard, onion, and tomatoes. Sprinkle with the pepper and top with the mozzarella. Return to the grill and grill, covered, until golden brown on the bottom and the cheese has melted, about 3 minutes. Cut each pizza in half."]),
mk2("cherry-thyme-stuffed-pork","Cherry and Thyme–Stuffed Pork",110,"Beef, Pork & Ham",["pork","roast","party"],"8",
 "Pork loin butterflied, rolled around a cherry-thyme stuffing, and roasted with a cherry glaze.",
 ["⅓ cup dried cherries, chopped","½ cup cherry all-fruit spread","3 tbsp plain dried bread crumbs","4 tsp chopped fresh thyme","1 (1½-pound) lean boneless center-cut pork loin, trimmed","¾ tsp salt","¼ tsp black pepper","Nonstick spray"],
 ["Preheat the oven to 400°F. Set a rack in a roasting pan and spray the rack and pan with nonstick spray.","For the stuffing, cover the cherries with boiling water in a small bowl. Let soak until softened, about 10 minutes; drain well. Stir in ¼ cup of the fruit spread, the bread crumbs, and thyme until well mixed.","With a long thin knife, cut the pork lengthwise in half, cutting about three-fourths of the way through, and open it like a book. Put it cut side down between two sheets of wax paper and gently pound to ½-inch thickness. Remove the top sheet and sprinkle the pork with the salt and pepper. Turn the pork over and spoon the cherry mixture down the center. Roll up lengthwise to enclose the filling and tie in 4 or 5 places with kitchen string.","Put the pork on the rack and roast 45 minutes. Brush with 1 tbsp of the fruit spread. Roast until an instant-read thermometer in the center reads 145°F, about 15 minutes longer, brushing 3 more times with the remaining spread. Move to a cutting board and let stand 10 minutes. Cut off and discard the string. Cut into 24 (¼-inch) slices."],
 ["Can be stuffed and refrigerated up to 6 hours ahead; leave out at room temperature about 20 minutes before roasting."]),
mk2("polenta-pizza-margherita","Polenta \"Pizza\" Margherita",116,"Sandwiches & Pizza",["polenta","vegetarian","broiler"],"4",
 "Browned polenta round topped with ricotta-Parmesan, tomato slices, and mozzarella, broiled.",
 ["1 (1-pound) tube plain fat-free polenta, cut into ¼-inch rounds","¾ cup part-skim ricotta cheese","¼ cup grated Parmesan cheese","¼ tsp black pepper","3 plum tomatoes, thinly sliced into rounds and patted dry with paper towels","½ cup shredded part-skim mozzarella cheese","Nonstick spray"],
 ["Preheat the broiler. Spray a 10-inch pizza pan or large baking sheet with nonstick spray.","Put 1 polenta slice in the center of the pan. Arrange the remaining slices in two concentric circles around it, slightly overlapping, to form a 10-inch polenta round. Lightly spray with nonstick spray. Broil 5 inches from the heat until lightly browned and heated through, about 8 minutes.","Meanwhile, stir the ricotta, Parmesan, and pepper together in a small bowl.","Arrange the tomato slices on the polenta and dollop with the ricotta-Parmesan mixture; sprinkle with the mozzarella. Broil until the tomatoes are heated through and the mozzarella has melted, about 4 minutes. Cut into 4 wedges."]),
mk2("roasted-brussels-sprouts-walnuts","Roasted Brussels Sprouts with Walnuts",122,"Vegetables & Sides",["vegetable","roasted","bacon"],"8",
 "Roasted Brussels sprouts and shallots tossed with crisp bacon and toasted walnuts.",
 ["2 pints Brussels sprouts, trimmed and halved or quartered if large","4 large shallots, thickly sliced","2 tbsp olive oil","½ tsp salt","¼ tsp black pepper","4 slices center-cut bacon, crisp-cooked and torn into ½-inch pieces","¼ cup walnuts, chopped and toasted"],
 ["Preheat the oven to 450°F.","Combine the Brussels sprouts and shallots on a large rimmed baking sheet. Drizzle with the oil and sprinkle with the salt and pepper, tossing to coat. Spread in an even layer. Roast until the sprouts and shallots are tender, about 20 minutes, stirring once or twice.","Move to a serving bowl. Add the bacon and walnuts and toss until well mixed."]),
mk2("sesame-broccoli","Sesame Broccoli",124,"Vegetables & Sides",["vegetable","vegan","quick"],"4",
 "Steamed broccoli tossed in a soy, honey, sesame oil, and garlic dressing.",
 ["4 cups small broccoli florets","2 tbsp soy sauce","1 tbsp honey","2 tsp Asian (dark) sesame oil","2 tsp toasted sesame seeds","1 garlic clove, crushed through a press"],
 ["Put the broccoli in a steamer basket set in a large saucepan over 1 inch of boiling water. Cover and steam until crisp-tender, about 4 minutes.","Meanwhile, stir the soy sauce, honey, sesame oil, sesame seeds, and garlic together in a serving bowl. Add the broccoli and toss until well mixed."],
 ["Add a thinly sliced large red bell pepper to the steamer with the broccoli."]),
mk2("carrot-horseradish-puree","Carrot-Horseradish Puree",128,"Vegetables & Sides",["vegetable","thanksgiving","holiday"],"4",
 "Silky carrot puree with butter and a bit of prepared horseradish. Good for Thanksgiving.",
 ["1½ pounds carrots, very thinly sliced","1 tbsp reduced-fat (2%) milk","1 tbsp butter","1 tbsp prepared horseradish","½ tsp salt, or to taste","¼ tsp black pepper"],
 ["Bring a large saucepan of water to a boil. Add the carrots and return to a boil. Reduce the heat and simmer, covered, until very tender, about 15 minutes. Drain well.","Process the carrots, milk, and butter in a food processor until very smooth. Move to a serving bowl and stir in the horseradish, salt, and pepper."]),
mk2("cauliflower-lemon-cumin","Cauliflower with Lemon and Cumin",129,"Vegetables & Sides",["vegetable","roasted","vegan"],"4",
 "Roasted cauliflower with cumin, then lemon zest, juice, and garlic.",
 ["1 small head cauliflower, cut into small florets","2 tsp olive oil","½ tsp ground cumin","½ tsp salt","¼ tsp black pepper","Grated zest and juice of ½ lemon","1 garlic clove, minced"],
 ["Preheat the oven to 450°F.","Put the cauliflower on a large rimmed baking sheet. Drizzle with the oil and sprinkle with the cumin, salt, and pepper. Toss to coat and spread in an even layer.","Roast 15 minutes, stirring once. Sprinkle with the lemon zest and juice and the garlic, tossing to coat. Roast until tender, about 3 minutes longer."],
 ["Good with grilled or broiled chicken, salmon, shrimp, or calamari."]),
mk2("whole-roasted-tandoori-cauliflower","Whole Roasted Tandoori Cauliflower",null,"Vegetables & Sides",["vegetable","roasted","showstopper"],"6",
 "A whole cauliflower coated in tandoori yogurt and roasted until golden and tender.",
 ["1 large head cauliflower","⅔ cup plain fat-free Greek yogurt","2 garlic cloves, minced","1½ tsp tandoori seasoning","½ tsp salt","2 tbsp chopped fresh cilantro","Nonstick spray"],
 ["Preheat the oven to 400°F. Spray a 9-inch pie plate or small shallow baking dish with nonstick spray.","Remove the outer leaves and core from the cauliflower and discard, keeping the head intact. Put it core side down in the dish. Whisk the yogurt, garlic, tandoori seasoning, and salt in a small bowl and spread evenly over the cauliflower.","Roast until a small knife goes into the center easily and the topping is browned, about 1 hour 30 minutes, rotating the dish once or twice so it cooks evenly.","Let stand 10 minutes. Sprinkle with the cilantro and cut into 6 wedges."],
 ["Can be roasted several hours ahead and reheated in the microwave."]),
mk2("grilled-parmesan-corn-cob","Grilled Parmesan Corn on the Cob",132,"Vegetables & Sides",["vegetable","grill","summer"],"8",
 "Foil-wrapped grilled corn brushed with cilantro-lime mayonnaise and sprinkled with Parmesan.",
 ["8 ears of corn","⅔ cup reduced-fat mayonnaise","¼ cup chopped fresh cilantro","Grated zest and juice of 1 lime","¼ cup grated Parmesan cheese"],
 ["Preheat the grill to medium-high or prepare a medium-high fire.","Gently pull the husks down from the corn and remove the silk. Pull the husks back over the corn.","Wrap each ear in a sheet of heavy foil. Put on the grill rack and grill, turning occasionally, until very tender, about 15 minutes.","Meanwhile, mix the mayonnaise, cilantro, and lime zest and juice in a cup.","Remove the husks, brush the corn all over with the mayonnaise mixture, and sprinkle with the Parmesan."],
 ["Add 1–2 tsp chili powder or a pinch of cayenne to the mayonnaise mixture for heat."])

,
mk2("tomato-garlic-stuffed-peppers","Tomato and Garlic–Stuffed Peppers",144,"Vegetables & Sides",["vegetable","roasted","gluten-free"],"4",
 "Red pepper halves packed with cherry tomatoes, garlic, anchovy, and rosemary, then roasted until browned and soft.",
 ["4 red bell peppers","48 cherry tomatoes (about 1½ pounds)","2 garlic cloves, thinly sliced","3 anchovies packed in oil, thinly sliced, plus 2½ tsp of the oil, reserved","2 large sprigs fresh rosemary or thyme","⅛ tsp salt","⅛ tsp black pepper","Nonstick spray"],
 ["Preheat the oven to 375°F. Line a large rimmed baking sheet with foil and spray with nonstick spray.","Cut the peppers in half lengthwise, cutting through the middle of each stem so it stays intact. Remove the cores and seeds. Set the halves cut side up on the baking sheet.","Fit about 6 whole cherry tomatoes into each pepper half. Tuck in the garlic and anchovies, dividing evenly. Break the rosemary into small sprigs and tuck them between the tomatoes. Drizzle with the reserved anchovy oil and sprinkle with salt and pepper.","Roast until the peppers are tender and browned along the edges and the tomatoes are softened, about 40 minutes."],
 ["Assorted-color peppers (orange, yellow, purple, green) make a colorful plate."]),
mk2("quick-cook-fresh-tomato-sauce","Quick-Cook Fresh Tomato Sauce",146,"Sauces & Gravies",["sauce","vegetarian","summer"],"8",
 "A light, fast sauce from ripe fresh tomatoes, best in the warmer months.",
 ["3 tbsp olive oil","1 small onion, chopped","4 large garlic cloves","2 pounds ripe tomatoes, cored and diced, juice reserved","1 tbsp tomato paste","2 tsp kosher salt","¼ tsp black pepper","½ cup chopped fresh basil"],
 ["Heat the oil in a large saucepan over medium heat. Add the onion and cook, stirring, until softened, about 5 minutes. Add the garlic and cook, stirring often, until fragrant, about 30 seconds.","Add the tomatoes with their juice, the tomato paste, salt, and pepper. Cook, stirring, until the tomatoes break down and begin to soften, about 4 minutes. Stir in the basil."],
 ["Serving size is about ½ cup."]),
mk2("grilled-zucchini-feta-lemon","Grilled Zucchini with Feta and Lemon",147,"Vegetables & Sides",["vegetable","grill","summer"],"6",
 "Grilled zucchini spears topped with a lemony feta and scallion mixture.",
 ["½ cup crumbled reduced-fat feta cheese","3 scallions, thinly sliced","1 tbsp extra-virgin olive oil","Grated zest of 1 lemon","4 (6-ounce) zucchini, ends trimmed","½ tsp kosher salt","¼ tsp black pepper","Olive oil nonstick spray"],
 ["Spray the grill rack with nonstick spray. Preheat the grill to high or prepare a hot fire.","Stir the feta, scallions, oil, and lemon zest together in a small bowl; set aside.","Cut the zucchini lengthwise in half, then cut each half into 4 or 5 pieces. Put in a large bowl, lightly spray with olive oil nonstick spray, and sprinkle with salt and pepper, tossing to coat.","Grill the zucchini, turning, until well marked and tender, about 6 minutes. Transfer to a platter or serving bowl and sprinkle with the feta mixture."],
 ["A small handful of thinly sliced or torn fresh mint is a good addition."]),
mk2("curried-barley-apricots","Curried Barley with Apricots",152,"Vegetables & Sides",["grain","vegetarian","make-ahead"],"6",
 "Toasted pearl barley with Madras curry, scallions, pistachios, and dried apricots.",
 ["¾ cup pearl barley","1 tbsp Madras curry powder","2½ cups water","¾ tsp salt","2 tsp olive oil","1 cup sliced scallions (about 4 large)","¼ cup chopped pistachios","3 tbsp chopped dried apricots","Olive oil nonstick spray"],
 ["Spray a large heavy saucepan with nonstick spray and set over medium heat. Add the barley and 2 tsp of the curry powder and cook, stirring often, until lightly toasted and fragrant, about 5 minutes.","Add the water and ½ tsp of the salt and bring to a boil. Reduce the heat and simmer, covered, until the barley is tender, about 35 minutes. Drain off any excess liquid and transfer the barley to a serving bowl.","Heat the oil in the same saucepan over medium heat. Add the scallions, the remaining 1 tsp curry powder, and the remaining ¼ tsp salt and cook, stirring, until the scallions are tender and fragrant, about 2 minutes.","Add the scallion mixture, pistachios, and apricots to the barley. Stir until mixed well."],
 ["About ¼ cup chopped or torn fresh mint adds another layer of flavor."]),
mk2("spicy-bulgur-carrots-harissa","Spicy Bulgur with Carrots and Harissa",158,"Vegetables & Sides",["grain","vegetarian","quick"],"4",
 "Quick-cooking bulgur tossed with carrots, peas, harissa, and cilantro.",
 ["2 cups water","1 cup quick-cooking bulgur","½ tsp salt","¼ tsp black pepper","1 cup shredded or matchstick-cut carrots","1 cup frozen baby peas, thawed","¾ tsp harissa","½ cup chopped fresh cilantro"],
 ["Combine the water, bulgur, salt, and pepper in a large saucepan and bring to a boil. Reduce the heat and simmer, covered, until the bulgur is tender and the water is absorbed, about 10 minutes.","Add the carrots, peas, and harissa and cook, stirring, until the carrots are just tender, about 2 minutes. Stir in the cilantro."],
 []),
mk2("mashed-parsnips-potatoes-apple","Mashed Parsnips, Potatoes, and Apple",163,"Vegetables & Sides",["vegetable","comfort","gluten-free"],"6",
 "Parsnips, Yukon Gold potatoes, and apple mashed together with browned butter and thyme.",
 ["1 pound parsnips, peeled and cut into ½-inch slices","1 pound Yukon Gold potatoes, peeled and cut into ¾-inch chunks","1 large McIntosh apple, peeled, cored, and cut into ¾-inch chunks","1 cup water","2 tbsp unsalted butter","½ tsp chopped fresh thyme","1 tsp salt","⅛ tsp black pepper"],
 ["Combine the parsnips, potatoes, apple, and water in a large saucepan over medium heat. Cook, covered, stirring occasionally, until the vegetables are softened, about 20 minutes.","Meanwhile, melt the butter in a small nonstick skillet over medium heat and cook until it starts to foam. Swirl the pan and cook until the foam subsides and the milk solids turn brown. Pour over the parsnip mixture.","Mash with a potato masher until it forms a coarse puree. Stir in the thyme, salt, and pepper. Stir in a bit of water if it seems dry, reheating over low heat if needed before serving."],
 []),
mk2("crispy-hasselback-potatoes","Crispy Hasselback Potatoes",165,"Vegetables & Sides",["potato","vegetarian","gluten-free"],"4",
 "Sliced-but-attached Yukon Golds roasted until browned and crisp; also known as accordion potatoes.",
 ["4 (5-ounce) Yukon Gold potatoes, scrubbed","2 tsp olive oil","1 large garlic clove, minced","½ tsp salt","¼ tsp black pepper","Maldon sea salt (optional)"],
 ["Preheat the oven to 425°F. Line a small rimmed baking sheet with parchment paper.","Peel the potatoes, leaving a lengthwise strip of skin on one long side of each. Set skin side down on a cutting board. With a thin sharp knife, cut each potato crosswise into ⅛-inch slices, stopping about ¼ inch from the bottom.","Drizzle with the oil, gently separating the slices so the oil can seep down. Sprinkle with the garlic, salt, and pepper, separating the slices so the seasoning coats every slice.","Place skin side down on the baking sheet and bake until browned and tender, about 50 minutes. Sprinkle with Maldon salt, if using."],
 ["Add some finely minced fresh thyme along with the garlic."]),
mk2("cast-iron-skillet-potato-kugel","Cast-Iron Skillet Potato Kugel",166,"Vegetables & Sides",["potato","gluten-free","holiday"],"8",
 "Shredded potato and onion baked in a hot skillet until golden and crisp on top; potato starch keeps it light.",
 ["1 onion, cut into chunks","2 pounds small russet potatoes, peeled","2 large eggs, lightly beaten","¼ cup potato starch","1½ tsp kosher salt","¼ tsp black pepper","2 tbsp olive oil","Olive oil nonstick spray"],
 ["Preheat the oven to 350°F.","Finely chop the onion in a food processor and transfer to a large bowl. To get long shreds, trim the potatoes so they fit horizontally in the feed tube. With the shredding blade in place, shred the potatoes and add to the onion. Add the eggs, potato starch, salt, and pepper and stir until mixed well.","Heat the oil in a 10-inch cast-iron or other heavy ovenproof skillet over medium-high heat until very hot. Add the potato mixture (it should sizzle), spreading it in an even layer and twisting the shreds on top into a decorative pattern. Spray with nonstick spray.","Bake until golden and crisp on top and tender when a knife is inserted, about 1 hour 10 minutes.","Cut into 8 wedges and sprinkle with extra salt and pepper if desired."],
 ["Potato starch is not the same as potato flour.","Add 2 tsp chopped fresh thyme or rosemary along with the eggs in step 2."]),
mk2("cheddar-potato-fries","Cheddar Potato “Fries”",167,"Vegetables & Sides",["potato","baked","kid-friendly"],"4",
 "Oven-baked russet fries finished with melted Cheddar.",
 ["2 (9-ounce) russet potatoes","¼ tsp salt","¼ tsp black pepper","½ cup shredded reduced-fat Cheddar cheese","Nonstick spray"],
 ["Preheat the oven to 400°F. Line a large rimmed baking sheet with a silicone baking mat or parchment paper.","Peel the potatoes and cut into ¼-inch-thick matchstick strips (about 52 total). Put on the baking sheet, spray with nonstick spray, and sprinkle with salt and pepper, tossing to coat. Spread in an even layer so they do not overlap or touch.","Bake 20 minutes. Turn the fries over and spread out. Bake until golden brown, about 20 minutes longer. Gather the fries together and sprinkle with the Cheddar. Bake until the cheese melts, about 5 minutes longer. Transfer the fries on the baking sheet to a wire rack and let cool slightly before serving."],
 ["Keep the potatoes separated on the sheet so the oven heat reaches every side."]),
mk2("german-potato-sauerkraut-salad","German-Style Potato-Sauerkraut Salad",168,"Vegetables & Sides",["potato","salad","picnic"],"6",
 "Warm red potatoes with smoked turkey, scallions, and sauerkraut.",
 ["8 small red potatoes, scrubbed","1 (¼-pound) piece skinless smoked turkey breast, cut into ½-inch dice","2 scallions, thinly sliced","1 tbsp extra-virgin olive oil","1–1½ tsp caraway seeds, crushed (optional)","½ tsp salt","¼ tsp black pepper","12 ounces fresh sauerkraut (bagged or jarred), undrained (about 2 cups), at room temperature"],
 ["Combine the potatoes with enough salted water to cover by 1 inch in a small saucepan and bring to a boil. Reduce the heat and simmer until fork-tender, about 12 minutes. Drain and let cool about 5 minutes. Cut the warm potatoes into quarters.","Combine the potatoes, turkey, scallions, oil, caraway seeds (if using), salt, and pepper in a serving bowl. Add the sauerkraut and gently toss until combined."],
 ["A little mustard would be a good addition."]),
mk2("smashed-potatoes-lemon-salt","Smashed Potatoes with Lemon Salt",171,"Vegetables & Sides",["potato","vegetarian","gluten-free"],"4",
 "Boiled baby potatoes flattened and pan-crisped, finished with lemon salt, toasted garlic chips, and parsley.",
 ["4 (¼-pound) red or yellow potatoes, scrubbed","¾ tsp kosher or coarse sea salt","½ tsp grated lemon zest","2 tsp extra-virgin olive oil","1 large garlic clove, thinly sliced","1 tbsp chopped fresh parsley"],
 ["Combine the potatoes with enough salted water to cover by 1 inch in a medium saucepan and bring to a boil. Reduce the heat and simmer, covered, until fork-tender, about 25 minutes. Drain and let cool about 5 minutes.","Meanwhile, combine the salt and lemon zest in a cup, rubbing them together with your fingers to bring out the lemon oil. Set aside.","Put the potatoes on a cutting board and gently press down on each with the palm of your hand or a pancake spatula to flatten slightly (the edges will split).","Combine the oil and garlic in a large nonstick skillet over medium heat. Cook, stirring, until the garlic is lightly toasted, about 1 minute. With a slotted spoon, lift out the garlic and transfer to a separate cup.","Add the potatoes to the skillet and cook over medium-high heat until browned and crisp on the bottom, about 5 minutes. Gently turn and cook until the second side is browned and crisp, about 5 minutes longer. Transfer to a small platter and sprinkle with the lemon salt, garlic chips, and parsley."],
 ["With 8 smaller (2-ounce) potatoes, cooking time drops to about 12 minutes."]),
mk2("classic-french-potato-salad","Classic French Potato Salad",172,"Vegetables & Sides",["potato","salad","picnic"],"6",
 "Warm Yukon Golds tossed with champagne vinegar, herbs, scallions, and shallot.",
 ["6 (¼-pound) Yukon Gold potatoes, peeled","2 tbsp champagne vinegar","⅓–½ cup chopped fresh herbs, such as parsley, dill, and basil","2 scallions, finely chopped","1 large shallot, finely chopped (⅓ cup)","2 tbsp extra-virgin olive oil","¾ tsp salt","¼ tsp black pepper, or to taste"],
 ["Combine the potatoes with enough salted water to cover by 1 inch in a medium saucepan and bring to a boil. Reduce the heat and simmer, covered, until tender, about 20 minutes. Drain and let cool about 5 minutes. Cut into ¾-inch chunks and transfer to a serving bowl.","Sprinkle the vinegar over the warm potatoes and gently toss to coat. Let stand 5 minutes, tossing once or twice. Add the herbs, scallions, shallot, oil, salt, and pepper and gently toss until mixed well. Let stand about 10 minutes. Serve warm or at room temperature."],
 ["Tossing still-warm potatoes with a liquid like vinegar or stock lets them absorb it and season all the way through."]),
mk2("red-quinoa-parsley-pine-nuts","Red Quinoa with Parsley and Pine Nuts",175,"Vegetables & Sides",["grain","vegetarian","quick"],"6",
 "Red quinoa dressed with white wine vinegar, parsley, and toasted pine nuts.",
 ["2 cups water","1 cup red quinoa","½ tsp salt, or to taste","1½ tbsp white wine vinegar","2 tsp extra-virgin olive oil","¼ tsp black pepper","⅓ cup chopped fresh flat-leaf parsley","3 tbsp pine nuts, toasted"],
 ["Bring the water to a boil in a small saucepan; stir in the quinoa and salt. Reduce the heat and simmer, covered, until the water is absorbed and the quinoa is tender, about 15 minutes. Remove from the heat and let stand 5 minutes; fluff with a fork.","Whisk the vinegar, oil, and pepper together in a serving bowl. Add the quinoa, parsley, and pine nuts and toss until mixed well. Season with more salt if desired."],
 ["Rinse quinoa before cooking unless the package says “prerinsed.”"]),
mk2("polenta-spinach-cheese","Polenta with Spinach and Cheese",177,"Vegetables & Sides",["grain","vegetarian","quick"],"4",
 "Quick-cooking polenta whisked into chicken broth with baby spinach and Parmesan.",
 ["2 cups reduced-sodium chicken broth","½ cup instant polenta","4 cups lightly packed baby spinach","¼ tsp salt","¼ tsp black pepper","¼ cup grated Parmesan cheese"],
 ["Bring the broth to a boil in a medium saucepan over medium-high heat. Whisk in the polenta in a thin, steady stream. Stir in the spinach, salt, and pepper.","Reduce the heat to medium-low and cook, stirring occasionally, until the polenta has thickened, about 4 minutes. Remove from the heat and stir in the Parmesan. Serve immediately."],
 ["Homemade stock from the freezer works well here."]),
mk2("real-deal-fried-rice","The Real Deal Fried Rice",178,"Pasta & Rice",["rice","quick","skillet"],"6",
 "Fried rice with ham, mini sweet peppers, scallions, and egg, made without soy sauce.",
 ["1 tsp canola or peanut oil","1 (6-ounce) piece lean ham steak, diced","4 mini sweet peppers in assorted colors, diced (1 cup)","5 scallions, sliced (green and white parts separated)","2 (8½-ounce) pouches ready-to-serve basmati rice","¼ cup water","½ tsp salt","⅛ tsp black pepper","2 large eggs, beaten"],
 ["Heat the oil in a large nonstick skillet over high heat. Add the ham, peppers, and white part of the scallions and cook, stirring occasionally, until the peppers are tender and lightly colored in spots, about 6 minutes.","Add the rice, water, salt, and pepper and cook, breaking up the rice and scraping the bottom of the skillet to lift any browned bits, until the rice is hot, about 3 minutes.","Push the rice to one side of the skillet and pour the eggs into the empty side. Cook until the eggs begin to set on the bottom, about 1 minute; stir and cook until set, breaking them up, 2 minutes longer. Stir the eggs and green part of the scallions into the rice."],
 ["Leaving out the soy sauce is traditional in China; serve it at the table if you like."]),
mk2("coconut-cardamom-basmati-rice","Coconut-Cardamom Basmati Rice",180,"Pasta & Rice",["rice","vegetarian","easy"],"6",
 "Brown basmati simmered in water and light coconut milk with cardamom.",
 ["1 cup water","1 cup brown basmati rice","1 cup light (low-fat) coconut milk","½ tsp ground cardamom","½ tsp salt","⅛ tsp black pepper"],
 ["Bring the water to a boil in a medium saucepan. Add the rice, coconut milk, cardamom, salt, and pepper and return to a boil. Reduce the heat and simmer, covered, until the rice is tender and the liquid is absorbed, about 40 minutes."],
 ["Good with broiled or grilled salt-and-pepper shrimp."]),
mk2("roasted-garlic-herb-bread","Roasted Garlic–Herb Bread",181,"Vegetables & Sides",["bread","vegetarian","party"],"6",
 "Whole-grain baguette spread with roasted garlic, Parmesan, and Italian seasoning, then broiled.",
 ["1 head garlic","¼ cup grated Parmesan cheese","¾ tsp dried Italian seasoning","½ (12-ounce) whole-grain or whole wheat baguette, sliced lengthwise in half","Olive oil nonstick spray"],
 ["Preheat the oven to 375°F.","Cut the head of garlic crosswise in half. Lightly spray all over with nonstick spray and wrap tightly in foil. Set the package directly on the oven rack and roast until the garlic is very tender when squeezed, about 1 hour.","When cool enough to handle, unwrap and squeeze the pulp from each clove into a small bowl. Add the Parmesan and Italian seasoning and mash with a fork until smooth and combined.","Preheat the broiler.","Spread the garlic-Parmesan mixture over the cut sides of the bread. Place cut side up on a broiler rack and broil 5 inches from the heat until browned in spots and heated through, about 2 minutes. Cut into 12 pieces."],
 ["The garlic-Parmesan mixture is also good on steamed green beans, grilled chicken or salmon, or steamed baby potatoes."]),
mk2("plum-crostata","Plum Crostata",187,"Pies & Crisps",["dessert","fruit","baked"],"8",
 "A free-form pie of sliced plums folded into a store-bought piecrust.",
 ["4 large plums (about 1½ pounds), halved, pitted, and cut into thin wedges","⅓ cup plus 1 tbsp sugar","1½ tbsp all-purpose flour","¼ tsp ground cinnamon or ⅛ tsp freshly grated nutmeg","1 refrigerated piecrust (from a 14.1-ounce package), softened according to package directions","Nonstick spray"],
 ["Preheat the oven to 400°F. Line a large baking sheet with heavy foil or parchment paper; lightly spray with nonstick spray.","Toss the plums, ⅓ cup of the sugar, the flour, and cinnamon together in a medium bowl.","On a lightly floured surface with a floured rolling pin, roll the piecrust into a 13-inch round. Fold in quarters; transfer to the baking sheet and gently unfold, being careful not to stretch the dough.","Pile the plum mixture on the crust, leaving a 1½- to 2-inch border. Scatter any sugar mixture left in the bowl over the plums. Fold the edge of the crust over the filling, pleating as you go. Sprinkle the remaining 1 tbsp sugar over the plums. Bake until the filling is bubbly and the crust is golden, about 45 minutes. Cool on the baking sheet on a wire rack."],
 [])

,
mk2("matcha-chocolate-meringue-bark","Matcha-Chocolate Meringue Bark",192,"Candy & Treats",["dessert","gluten-free","make-ahead"],"16",
 "Crisp pale-green meringue with mini chocolate chips and toasted sesame seeds, broken into pieces.",
 ["1 tbsp water","2 tsp matcha (green tea powder)","5 large egg whites, at room temperature","½ cup superfine sugar","2 tbsp mini semisweet chocolate chips","4 tsp toasted sesame seeds"],
 ["Preheat the oven to 250°F. Line a large rimmed baking sheet with parchment paper.","Stir the water and matcha together in a cup. With an electric mixer on medium speed, beat the egg whites in a large bowl until soft peaks form when the beaters are lifted. Beat in the sugar, 1 tablespoon at a time, until stiff, glossy peaks form. Beat in the matcha mixture until the meringue is pale green, about 1 minute longer.","Put a dab of meringue under each corner of the parchment to hold it in place. Pile the meringue on the parchment and spread with an offset spatula into a 9 x 12-inch rectangle (about ¾ inch thick). Sprinkle the chocolate chips and sesame seeds evenly over the top.","Bake until the meringue looks dry and set but is slightly soft in the center when gently pressed, about 2½ hours. Turn off the oven and leave the meringue inside until firm and crisp, at least 4 hours or up to overnight. (It will turn light beige.)","Turn the bark over with the parchment and carefully peel off the paper. Turn right side up and gently cut into 16 pieces with a serrated knife."],
 ["Make on a low-humidity day or the meringue won't crisp.","Best served the day it is made."]),
mk2("banana-chocolate-chip-ice-cream","Banana–Chocolate Chip “Ice Cream”",193,"Puddings & Desserts",["dessert","no-churn","vegetarian"],"4",
 "Frozen bananas pureed until creamy, with mini chocolate chips and toasted almonds.",
 ["4 ripe large bananas","½ tsp vanilla extract","¼ cup mini semisweet chocolate chips","2 tbsp sliced almonds, toasted"],
 ["Peel the bananas and cut into 1-inch chunks. Put in a large zip-close plastic bag, squeeze out the air, and seal. Freeze until solid, at least 3 hours or up to overnight.","Puree the frozen bananas in a food processor, scraping down the sides once or twice. Add the vanilla and pulse until mixed. Transfer to a medium bowl and stir in the chocolate chips.","Scoop into 4 dessert dishes and sprinkle with the almonds. Or cover and freeze up to 1 day, leaving it out on the counter about 10 minutes for easier scooping."],
 []),
mk2("vanilla-bean-panna-cotta","Vanilla Bean Panna Cotta",195,"Puddings & Desserts",["dessert","make-ahead","italian"],"4",
 "A light eggless custard of buttermilk and half-and-half, set with gelatin.",
 ["1¼ tsp unflavored gelatin","2 tbsp cold water","1 vanilla bean, split, or ¾ tsp vanilla extract","1 cup low-fat buttermilk","¾ cup half-and-half","¼ cup sugar","Nonstick spray"],
 ["Lightly spray 4 (5-ounce) ramekins, (6-ounce) custard cups, or wineglasses with nonstick spray.","Sprinkle the gelatin over the water in a cup. Let stand until softened, about 5 minutes.","Meanwhile, split the vanilla bean and scrape out the seeds with the edge of a small knife, keeping both the pod and seeds.","Combine the buttermilk, half-and-half, sugar, and vanilla pod and seeds in a small saucepan over medium heat. Cook, whisking occasionally, until hot and the sugar has dissolved, 4–5 minutes. Remove from the heat and whisk in the gelatin mixture until completely dissolved. Pour through a sieve set over a medium bowl or glass measure. Stir in the vanilla extract, if using.","Divide evenly among the ramekins. Refrigerate until chilled and set, at least 4 hours or up to 1 day."],
 ["Top each with a few fresh raspberries.","Easily doubled for a dinner party."])
);

window.RECIPES = (window.RECIPES || []).concat(R);
})();
